def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) < 2:
        return out

    # Use the marker nearest the colored pattern as the source anchor.
    def dist_to_pattern(p):
        r, c = p
        return min(
            abs(r - i) + abs(c - j)
            for i in range(h) for j in range(w)
            if grid[i][j] not in (0, 5)
        )

    src = min(markers, key=dist_to_pattern)
    dst = next(p for p in markers if p != src)
    dr, dc = dst[0] - src[0], dst[1] - src[1]

    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 5):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = grid[r][c]
    return out
